import Phaser from 'phaser';
export class PlayerController {
  constructor(scene, sprite) { this.scene = scene; this.sprite = sprite; this.hp = 100; this.mana = 74; this.gold = 24500; this.combo = 0; this.state = 'idle'; this.iframes = 0; this.attackTimer = 0; this.cancelWindow = 0; }
  update(input, dt) { const body = this.sprite.body; const accel = body.blocked.down ? 980 : 680; body.setVelocityX(Phaser.Math.Clamp(body.velocity.x + input.axisX * accel * dt, -230, 230)); if (!input.axisX && body.blocked.down) body.setVelocityX(Phaser.Math.Linear(body.velocity.x, 0, 0.22)); if (input.axisX) this.sprite.setFlipX(input.axisX < 0); if (input.consume('jump') && body.blocked.down) body.setVelocityY(-470); if (input.consume('dash') && this.mana >= 8) { this.mana -= 8; body.setVelocityX((this.sprite.flipX ? -1 : 1) * 480); this.iframes = 0.24; this.scene.events.emit('dash'); } if (input.consume('attack') && (this.attackTimer <= 0 || this.cancelWindow > 0)) this.startAttack(); this.iframes = Math.max(0, this.iframes - dt); this.attackTimer = Math.max(0, this.attackTimer - dt); this.cancelWindow = Math.max(0, this.cancelWindow - dt); this.state = this.attackTimer ? 'attack' : !body.blocked.down ? 'air' : Math.abs(body.velocity.x) > 18 ? 'run' : 'idle'; this.sprite.setScale(1 + (this.state === 'attack' ? 0.08 : 0), 1 - (this.state === 'attack' ? 0.04 : 0)); }
  startAttack() { this.attackTimer = 0.34; this.cancelWindow = 0.09; this.combo = (this.combo % 3) + 1; this.scene.events.emit('player-attack', this); }
}
